using GestionTubos.Application.Interfaces;
using GestionTubos.Domain.Entities;
using GestionTubos.Domain.Enums;
using GestionTubos.Infrastructure.Data;
using GestionTubos.Infrastructure.Services;
using GestionTubos.Shared;
using GestionTubos.Shared.Operaciones;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.Extensions.Configuration;
using Microsoft.Data.SqlClient;
var root=args[0];var cfg=new ConfigurationBuilder().AddJsonFile(Path.Combine(root,"GestionTubos.Api","appsettings.json")).Build();var cs=new SqlConnectionStringBuilder(cfg.GetConnectionString("GestionTubos")){InitialCatalog="GestionTubos_PruebaPlanchadas_"+Guid.NewGuid().ToString("N")};var opts=new DbContextOptionsBuilder<GestionTubosDbContext>().UseSqlServer(cs.ConnectionString).Options;
GestionTubosDbContext Db()=>new(opts);await using var principal=Db();int checks=0;void Check(bool ok,string m){if(!ok)throw new Exception(m);checks++;}
async Task Rechaza(Func<Task> f,string m){try{await f();}catch(InvalidOperationException){checks++;return;}throw new Exception("Aceptó "+m);}
async Task Ingresar(int sector,params int[]ids){await using var d=Db();await new PlanchadaService(d,new Actor()).Ingresar(new(){SectorId=sector,TuboIds=ids.ToList()},"Operador ingreso",default);}
async Task Retirar(long uso,string resultado,int destino,string?motivo=null){await using var d=Db();await new PlanchadaService(d,new Actor()).Retirar(new(){UsoIds=[uso],Resultado=resultado,UbicacionDestinoId=destino,Motivo=motivo},"Operador retiro",default);}
async Task<List<UsoBateriaDto>>Activos(){await using var d=Db();return await new PlanchadaService(d).Activos(null,default);}
async Task<ConsumoInternoDto>Consumo(){await using var d=Db();return await new PlanchadaService(d).Consumo(DateOnly.FromDateTime(HoraArgentina.Hoy.AddDays(-1)),DateOnly.FromDateTime(HoraArgentina.Hoy.AddDays(1)),null,default);}
try{
 await principal.GetService<IMigrator>().MigrateAsync("20261015225121_AuditoriaYEdicionRemitos");
 await principal.Database.ExecuteSqlRawAsync("INSERT INTO Ubicaciones (Nombre,Descripcion,EsInterna,Activa) VALUES (N'Planta de prueba',NULL,1,1),(N'Fuera de planta',NULL,0,1)");await principal.Database.MigrateAsync();var planta=await principal.Ubicaciones.SingleAsync(x=>x.Nombre=="Planta de prueba");var externa=await principal.Ubicaciones.SingleAsync(x=>x.Nombre=="Fuera de planta");Check((await principal.Ubicaciones.SingleAsync(x=>x.Id==planta.Id)).Nombre=="Planta de prueba","Migración conserva ubicaciones previas");
 var svc=new PlanchadaService(principal,new Actor());await svc.InicializarAsync();await svc.InicializarAsync();var sectores=await svc.Sectores(default);Check(sectores.Count==3,"Tres sectores sin duplicar");var ox=sectores.Single(x=>x.Gas=="O2").Id;var ni=sectores.Single(x=>x.Gas=="N2").Id;
 var o2=await principal.TiposGas.FirstOrDefaultAsync(x=>x.Nombre=="O₂")??new TipoGas{Nombre="O₂"};if(o2.Id==0)principal.Add(o2);var n2=await principal.TiposGas.FirstOrDefaultAsync(x=>x.Nombre=="N₂")??new TipoGas{Nombre="N₂"};if(n2.Id==0)principal.Add(n2);var co2=new TipoGas{Nombre="CO₂ prueba"};var cap=new CapacidadTubo{Valor=17.5m,Unidad="m³"};var litros=new CapacidadTubo{Valor=50,Unidad="L"};var cliente=new Cliente{Nombre="Cliente",Apellido="Prueba",Tipo=(TipoCliente)1};principal.AddRange(co2,cap,litros,cliente);await principal.SaveChangesAsync();
 var tubos=Enumerable.Range(1,10).Select(i=>new Tubo{CodigoInterno="BAT-"+i,TipoGasId=o2.Id,CapacidadTuboId=cap.Id,TipoPropietario=TipoPropietarioTubo.Empresa,EstadoContenido=EstadoContenido.Lleno,EstadoDisponibilidad=EstadoDisponibilidad.Disponible,UbicacionId=planta.Id}).ToList();tubos[1].TipoGasId=n2.Id;tubos[2].EstadoContenido=EstadoContenido.Vacio;tubos[3].TipoPropietario=TipoPropietarioTubo.Cliente;tubos[3].ClientePropietarioId=cliente.Id;tubos[5].UbicacionId=externa.Id;tubos[6].EstadoFisico=EstadoFisico.Danado;tubos[7].TipoGasId=co2.Id;tubos[8].CapacidadTuboId=litros.Id;principal.AddRange(tubos);await principal.SaveChangesAsync();
 foreach(var t in tubos.Where((t,i)=>i!=4))principal.PruebasHidraulicas.Add(new(){TuboId=t.Id,FechaRealizacion=DateOnly.FromDateTime(HoraArgentina.Hoy.AddYears(-1)),FechaVencimiento=DateOnly.FromDateTime(HoraArgentina.Hoy.AddYears(1)),Aprobada=true,EntidadRealizadora="Prueba"});await principal.SaveChangesAsync();
 var candidatos=await svc.Candidatos(ox,default);Check(candidatos.Count==3&&candidatos.All(x=>x.Gas=="O₂"),"Candidatos excluyen vacío, tercero, PH inválida, externo, dañado y otro gas");
 await Rechaza(()=>Ingresar(ox,tubos[0].Id,tubos[1].Id),"mezcla de gases");Check((await Activos()).Count==0,"Ingreso inválido no mueve parte del lote");
 await Rechaza(()=>Ingresar(ox,tubos[0].Id,tubos[0].Id),"selección duplicada");await Ingresar(ox,tubos[0].Id,tubos[9].Id);var activos=await Activos();Check(activos.Count==2,"Ingreso por lote");
 await using(var d=Db()){var t=await d.Tubos.SingleAsync(x=>x.Id==tubos[0].Id);Check(t.EstadoDisponibilidad==EstadoDisponibilidad.EnBateria&&t.UbicacionId==ox,"En batería y ubicación correcta");var u=await d.UsosBateria.SingleAsync(x=>x.TuboId==t.Id);Check(u.UsuarioIngresoId=="usuario-bateria"&&u.CapacidadNominal==17.5m,"Usuario y capacidad histórica guardados");}
 Check((await Consumo()).PorGas.Count==0,"Ingresar no suma consumo");await Rechaza(()=>Ingresar(ox,tubos[0].Id),"doble ingreso");
 await Rechaza(async()=>{await using var d=Db();await new TuboService(d).EliminarAsync(tubos[0].Id,default);},"baja de tubo en batería");
 await Rechaza(async()=>{await using var d=Db();await new TuboService(d).ActualizarAsync(tubos[0].Id,new(){CodigoInterno="BAT-1",TipoGasId=o2.Id,CapacidadTuboId=cap.Id,UbicacionId=planta.Id,EstadoDisponibilidad=1,EstadoContenido=1},default);},"editar en batería");
 await Rechaza(async()=>{await using var d=Db();await new TuboService(d).UbicarPropiosAsync(new(){UbicacionDestinoId=planta.Id,Tubos=[new(){Id=tubos[0].Id,UbicacionOrigenId=ox}]},"Prueba",default);},"traslado de tubo en batería");
 await Rechaza(async()=>{await using var d=Db();await new TuboService(d).UbicarPropiosAsync(new(){UbicacionDestinoId=ox,Tubos=[new(){Id=tubos[8].Id,UbicacionOrigenId=planta.Id}]},"Prueba",default);},"ingresar por traslado genérico");
 await Rechaza(async()=>{await using var d=Db();await new PedidoService(d).CrearAsync(new(){ClienteId=cliente.Id,CilindroIds=[tubos[0].Id],ModalidadEntrega="RetiroPlanta"},"Prueba",default);},"entrega a cliente de un tubo en batería");
 var primero=activos.Single(x=>x.TuboId==tubos[0].Id);await Rechaza(()=>Retirar(primero.Id,"Lleno",planta.Id),"retirar lleno sin motivo");await Rechaza(()=>Retirar(primero.Id,"Agotado",ni),"retirar hacia otra planchada");await Retirar(primero.Id,"Agotado",planta.Id);
 Check((await Activos()).Count==1,"Retiro parcial de batería");var consumo=await Consumo();Check(consumo.PorGas.Single().TubosAgotados==1&&consumo.PorGas.Single().CapacidadNominalTotal==17.5m,"Solo agotados suman consumo");await Rechaza(()=>Retirar(primero.Id,"Agotado",planta.Id),"doble retiro");Check((await Consumo()).PorGas.Single().TubosAgotados==1,"Consumo no duplicado");
 await using(var d=Db()){var t=await d.Tubos.SingleAsync(x=>x.Id==tubos[0].Id);Check(t.EstadoContenido==EstadoContenido.Vacio&&t.EstadoDisponibilidad==EstadoDisponibilidad.Disponible&&t.UbicacionId==planta.Id,"Agotado vuelve vacío a stock");Check((await new CargaLoteService(d).Vacios(default)).Any(x=>x.Id==t.Id&&x.Apto),"Vacío disponible para carga externa");}
 await Retirar(activos.Single(x=>x.TuboId==tubos[9].Id).Id,"Parcial",planta.Id,"Cambio de batería");Check((await Consumo()).PorGas.Single().TubosAgotados==1,"Parcial no suma consumo completo");
 await Ingresar(ox,tubos[8].Id);await Retirar((await Activos()).Single().Id,"Lleno",planta.Id,"Retiro preventivo");Check((await Consumo()).PorGas.Count==1,"Lleno no suma consumo");
 await Ingresar(ox,tubos[8].Id);await Retirar((await Activos()).Single().Id,"Agotado",planta.Id);Check((await Consumo()).PorGas.Count==2,"Unidades distintas no se mezclan");
 await Ingresar(ni,tubos[1].Id);await using(var d=Db()){var ph=await d.PruebasHidraulicas.SingleAsync(x=>x.TuboId==tubos[1].Id);ph.FechaVencimiento=DateOnly.FromDateTime(HoraArgentina.Hoy.AddDays(-1));await d.SaveChangesAsync();}await Retirar((await Activos()).Single().Id,"Agotado",planta.Id);await using(var d=Db()){Check((await d.Tubos.SingleAsync(x=>x.Id==tubos[1].Id)).EstadoDisponibilidad==EstadoDisponibilidad.PendienteInspeccion,"PH vencida al retirar requiere revisión");}
 await Rechaza(async()=>{await using var d=Db();var u=await d.UsosBateria.SingleAsync(x=>x.Id==primero.Id);u.MotivoRetiro="Alterado";await d.SaveChangesAsync();},"alterar ciclo cerrado");
 await using(var d=Db()){var capGuardada=await d.CapacidadesTubo.SingleAsync(x=>x.Id==cap.Id);capGuardada.Valor=18;await d.SaveChangesAsync();Check((await new PlanchadaService(d).Consumo(DateOnly.FromDateTime(HoraArgentina.Hoy),DateOnly.FromDateTime(HoraArgentina.Hoy),ox,default)).PorGas.Single(x=>x.Unidad=="m³").CapacidadNominalTotal==17.5m,"Consumo conserva capacidad original");}
 await Rechaza(async()=>{await using var d=Db();await new CatalogoService(d).EliminarUbicacionAsync(ox,default);},"eliminar planchada");
 await using(var d=Db()){var hist=await new PlanchadaService(d).Historial(DateOnly.FromDateTime(HoraArgentina.Hoy),DateOnly.FromDateTime(HoraArgentina.Hoy),null,null,default);Check(hist.Registros.Count==5&&hist.Registros.All(x=>x.UsuarioRetiro=="Operador retiro"),"Historial incluye todos los resultados y responsable");Check((await new PlanchadaService(d).Consumo(DateOnly.FromDateTime(HoraArgentina.Hoy.AddDays(-4)),DateOnly.FromDateTime(HoraArgentina.Hoy.AddDays(-2)),null,default)).PorGas.Count==0,"Filtro temporal de consumo");}
 Console.WriteLine(checks+" verificaciones de planchadas, retiros, stock y consumo correctas.");
}finally{if(!cs.InitialCatalog.StartsWith("GestionTubos_PruebaPlanchadas_"))throw new Exception("Base inesperada");await principal.Database.EnsureDeletedAsync();}
sealed class Actor:IUsuarioActual{public string Id=>"usuario-bateria";}
